SELECT * FROM pcd_ip_blacklist_table
WHERE blacklist_status = 'ACTIVE'
AND (blacklist_expires_at IS NULL OR blacklist_expires_at > NOW());

mapper.insert:
INSERT INTO pcd_ip_blacklist_table (
