) VALUES (
    #{blacklistIp}, #{blacklistReason},
    #{blacklistAddedBy,typeHandler=org.project.util.UUIDBinaryTypeHandler},
    #{blacklistStatus}, #{blacklistExpiresAt}, #{blacklistCreatedAt}
);
